// Request message for composite verify redirect response flow.
message CompositeVerifyRedirectResponseRequest {
  // Identification
  optional string merchant_order_id = 1;
  optional string merchant_transaction_id = 2;

  // Request Details from redirect callback
  RequestDetails request_details = 3;

  // Security
  optional RedirectResponseSecrets redirect_response_secrets = 4;

  // Metadata needed for authorize (if required)
  optional SecretString metadata = 5;
  optional SecretString connector_feature_data = 6;

  // Environment Configuration
  optional bool test_mode = 7;

  // State Information (for access token, session token if needed)
  optional ConnectorState state = 8;

  // Payment data needed for authorize (if required)
  optional Money amount = 9;
  optional PaymentMethod payment_method = 10;
  optional CaptureMethod capture_method = 11;

  // Access Token
  optional string merchant_access_token_id = 12;

  // Server Session Token
  optional string merchant_server_session_id = 13;

  // Payment Experience
  optional PaymentExperience payment_experience = 14;

  // Browser Information (may be needed for authorize)
  optional BrowserInformation browser_info = 15;

  // Authentication type
  optional AuthenticationType auth_type = 16;

  // Customer Information
  optional Customer customer = 17;

  // Address Information
  optional PaymentAddress address = 18;

  // Amount Information
  optional int64 order_tax_amount = 19; // Tax amount for the order
  optional int64 shipping_cost = 20;    // Cost of shipping for the order

  // Authentication Details
  optional bool enrolled_for_3ds = 21;
  optional AuthenticationData authentication_data = 22;

  // URLs for Redirection and Webhooks
  optional string return_url = 23;
  optional string webhook_url = 24;
  optional string complete_authorize_url = 25; // URL to complete authorization

  // Session and Token Information
  optional string session_token = 26;

  // Order Details
  optional string order_category = 27;

  // Behavioral Flags and Preferences
  optional FutureUsage setup_future_usage = 28; // Indicates future usage intention
  optional bool off_session = 29;               // Indicates if off-session transaction
  optional bool request_incremental_authorization = 30; // Indicates if incremental authorization is requested
  optional bool request_extended_authorization = 31;    // Indicates if extended authorization is requested
  optional bool enable_partial_authorization = 32;      // Indicates if partial authorization is enabled

  // Contextual Information
  optional CustomerAcceptance customer_acceptance = 33; // Details of customer acceptance
  optional string description = 34;
  optional PaymentChannel payment_channel = 35; // Describes the channel through which the payment was initiated

  // Mandate Setup Details
  optional SetupMandateDetails setup_mandate_details = 36;

  optional string statement_descriptor_name = 37; // Complete description that appears on customers' statements
  optional string statement_descriptor_suffix = 38; // Provides information about a card payment that customers see on their statements

  // Statement Descriptor
  optional BillingDescriptor billing_descriptor = 39;

  // Order Details
  repeated OrderDetailsWithAmount order_details = 40; // Details about the different products for which the payment is being made

  // Locale Information
  optional string locale = 41; // Locale/language preference for the shopper (e.g., "en-US")

  // Tokenization configuration
  optional Tokenization tokenization_strategy = 42; // Tokenization strategy for payment processing

  // Indicates if 3DS method data was successfully completed or not
  optional ThreeDsCompletionIndicator threeds_completion_indicator = 43;

  // Redirection Information after DDC step
  optional RedirectionResponse redirection_response = 44; // Redirection Response from client browser

  // URL for Redirection
  optional string continue_redirection_url = 45; // URL to complete authorization

  // Level 2 / Level 3 data for enhanced payment processing
  optional L2L3Data l2_l3_data = 46;

  // Send the connector order identifier here if an order was created before authorize
  optional string connector_order_id = 47;

  // Request ID generated by the caller system for payment gateway requests.
  // Required by some connectors for authorize requests.
  optional string merchant_request_id = 48;

  // Connector-agnostic domain-specific data (airline, lodging, etc.).
  optional DomainData domain_data = 49;

  // Split payment configuration (platform fees, transfers, etc.)
  optional SplitPaymentsDetails split_payments = 50;

  // MIT Category — mirrors PaymentServiceAuthorizeRequest.mit_category.
  optional MitCategory mit_category = 51;

  // Surcharge amount to send separately for connectors that support a first-class
  // surcharge field. Mirrors PaymentServiceAuthorizeRequest.surcharge_amount.
  optional Money surcharge_amount = 52;

  // Information identifying partner and merchant application initiating the request
  optional PartnerMerchantIdentifierDetails partner_merchant_identifier_details = 53;

  // Currency conversion quote and customer decision supplied for
  // authorization after redirect verification.
  optional CurrencyConversionData currency_conversion_data = 54;
}

// Response message for composite verify redirect response flow.
message CompositeVerifyRedirectResponseResponse {
  // Verification result (always populated)
  PaymentServiceVerifyRedirectResponseResponse verify_redirect_response = 1;

  // Following fields are only populated if connector requires authorize post redirect
  optional MerchantAuthenticationServiceCreateServerAuthenticationTokenResponse access_token_response = 2;
  optional MerchantAuthenticationServiceCreateServerSessionAuthenticationTokenResponse session_token_response = 3;
  optional PaymentServiceAuthorizeResponse authorize_response = 4;
}

// Generic composite notify request that includes access token bootstrapping.
// Used by composite event service for FRM notification flows.
message CompositeNotifyRequest {
  // Unique event identifier
  string event_id = 1;

  // Event type
  NotifyEventType event_type = 2;

  // Event content with notify connector content
  NotifyConnectorContent content = 3;

  // Timestamp when the event occurred (Unix timestamp in seconds)
  int64 timestamp = 4;

  // Connector state for access token management (optional)
  optional ConnectorState state = 5;

  // Additional metadata for the connector
  optional SecretString metadata = 6;

  // Connector-specific feature data
  optional SecretString connector_feature_data = 7;

  // Sandbox/test mode flag
  optional bool test_mode = 8;

  // Reference ID for access token tracking
  optional string merchant_access_token_id = 9;

  // Per-request idempotency / correlation token
  optional string merchant_request_id = 10;
}

// Generic composite notify response that includes access token response.
// Used by composite event service for FRM notification flows.
message CompositeNotifyResponse {
  // The underlying notify connector response (always populated)
  NotifyConnectorResponse notify_response = 1;

  // Access token generation result (populated only when bootstrapped)
  optional MerchantAuthenticationServiceCreateServerAuthenticationTokenResponse access_token_response = 2;
}
